head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25302";
scwin.regForm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.checkPersonal();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25302.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_regForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.regForm = $c.util.getComponent('regForm');
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25302.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_mailDiv_onchange
 * @description slc_mailDiv 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_mailDiv_onchange = function(e){
    try {
        scwin.setMailDiv($c.util.getComponent("slc_mailDiv"))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25302.slc_mailDiv_onchange' }); }
};

/**
 * @method
 * @name btn_RegCertificate_onclick
 * @description btn_RegCertificate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RegCertificate_onclick = async function(e){
    try {
        await scwin.regCertificate()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25302.btn_RegCertificate_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25302.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_SignCallback
 * @description Sign Callback 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_SignCallback = async function () {
    const sbmOptions = {
        id: "tx_SignCallback",
        method: "post",
        action: "/account/popCertificate.do?method=registerCertificate&againYN=${(regMod == ",
        ref: "dma_SignCallbackReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckSendForm
 * @description Check Send Form 처리
 * @param {*} regForm regForm
 * @returns {void}
 * @hidden N
 */
scwin.CheckSendForm = function (regForm) {
    INIWEBEX.login({ loginType: "sign", data: "login", processCallback: "SignCallback", isHtml5: false, viewType: "NONE", iniCache: true, vid: true, langType: "KOR", filterCertByOIDAlias: { enable: false, list: "" }, filterCertByIssuer: { enable: true, list: realIssuerDN } });
};

/**
 * @method
 * @name SignCallback
 * @description Sign Callback 처리
 * @param {*} result result
 * @param {*} postData postData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.SignCallback = async function (result, postData) {
    $c.util.getComponent('dma_SignCallbackReq').set('PKCS7SignedData', result);
    if (result) {
        scwin.form_regForm.action = "/account/popCertificate.do?method=registerCertificate&againYN=${(regMod == 'MOD')?'Y':'N'}";
        await scwin.tx_SignCallback();
    } else {
        await $c.win.alert("전자서명에 실패하였습니다.");
    }
};

/**
 * @method
 * @name regCertificate
 * @description reg Certificate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regCertificate = async function () {
    const personalChk = $c.util.getComponent('ipt_personalCheck').getValue();
    if (personalChk !== 'Y') {
        if (await $c.win.confirm("개인정보 처리방침 및 수집·이용에 동의해주시기 바랍니다.")) {
            (Promise.resolve($c.win.openPopup("/personalInfo_layer/personalInfo_layer.xml", { id: "personalInfo", width: "800", height: "700", scrollbars: false, type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("personalInfo"); this.closed = true; } });
            return;
        } else {
            return;
        }
    }
    if (($c.util.getComponent('ipt_chrgNm').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) === '') {
        await $c.win.alert("담당자를 입력해 주세요.");
        $c.util.getComponent("ipt_chrgNm").focus();
        return;
    } else {
        if (($c.util.getComponent('ipt_chrgDepNm').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgDepNm').getValue())) === '') {
            await $c.win.alert("부서를 입력해 주세요.");
            $c.util.getComponent("ipt_chrgDepNm").focus();
            return;
        } else {
            if (($c.util.getComponent('ipt_chrgTelNo1').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgTelNo1').getValue())) === '') {
                await $c.win.alert("전화번호를 입력해 주세요.");
                $c.util.getComponent("ipt_chrgTelNo1").focus();
                return;
            } else {
                if (($c.util.getComponent('ipt_chrgTelNo2').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgTelNo2').getValue())) === '') {
                    await $c.win.alert("전화번호를 입력해 주세요.");
                    $c.util.getComponent("ipt_chrgTelNo2").focus();
                    return;
                } else {
                    if (($c.util.getComponent('ipt_chrgTelNo3').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgTelNo3').getValue())) === '') {
                        await $c.win.alert("전화번호를 입력해 주세요.");
                        $c.util.getComponent("ipt_chrgTelNo3").focus();
                        return;
                    } else {
                        if (($c.util.getComponent('ipt_chrgEmail1').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgEmail1').getValue())) === '') {
                            await $c.win.alert("Email을 입력해 주세요.");
                            $c.util.getComponent("ipt_chrgEmail1").focus();
                            return;
                        } else {
                            if (($c.util.getComponent('ipt_chrgEmail2').getValue() === null ? '' : String($c.util.getComponent('ipt_chrgEmail2').getValue())) === '') {
                                await $c.win.alert("Email을 입력해 주세요.");
                                $c.util.getComponent("ipt_chrgEmail2").focus();
                                return;
                            }
                        }
                    }
                }
            }
        }
    }
    $c.util.getComponent('dma_SignCallbackReq').set('chrgTelNo', $c.util.getComponent('ipt_chrgTelNo1').getValue()+ $c.util.getComponent('ipt_chrgTelNo2').getValue()+ $c.util.getComponent('ipt_chrgTelNo3').getValue());
    $c.util.getComponent('dma_SignCallbackReq').set('chrgEmail', $c.str.trim($c.util.getComponent('ipt_chrgEmail1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_chrgEmail2').getValue()));
    scwin.CheckSendForm(scwin.regForm);
};

/**
 * @method
 * @name setMailDiv
 * @description set Mail Div 처리
 * @param {*} mailObj mailObj
 * @returns {void}
 * @hidden N
 */
scwin.setMailDiv = function (mailObj) {
    $c.util.getComponent("ipt_chrgEmail2").setValue(mailObj.getValue());
    if ((mailObj.getValue() === null ? '' : String(mailObj.getValue())) === '') {
        $c.util.getComponent("ipt_chrgEmail2").focus();
    }
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name checkPersonal
 * @description check Personal 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPersonal = async function () {
    const personalChk = $c.util.getComponent('ipt_personalCheck').getValue();
    if (personalChk !== 'Y') {
        if (await $c.win.confirm("개인정보 처리방침 및 수집·이용에 동의해주시기 바랍니다.")) {
            (Promise.resolve($c.win.openPopup("/personalInfo_layer/personalInfo_layer.xml", { id: "personalInfo", width: "800", height: "700", scrollbars: false, type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("personalInfo"); this.closed = true; } });
            return;
        } else {
            return;
        }
    }
};
